head.script:
// 결함 재현 시나리오 설명
scwin.tData = {
    "description" : "[FAIL] radio / selectbox 컴포넌트의 setDisabled(true) 호출 후 비활성화 상태에서도 사용자가 컴포넌트를 클릭하면 일부 이벤트가 발생하는 결함 재현",
    "validation" : [
        "setDisabled(true) 호출 후 컴포넌트 클릭 시 onclick, onfocus, onchange 이벤트가 모두 차단되어야 합니다.",
        "현재 실제 동작 (radio) : setDisabled(true) 상태에서 radio 항목 클릭 시 onfocus, onclick 이벤트가 발생합니다 (onchange 만 정상 차단).",
        "현재 실제 동작 (selectbox) : setDisabled(true) 상태에서 selectbox 클릭 시 onclick 이벤트가 발생합니다 (onfocus, onchange 는 정상 차단)."
    ]
}



scwin.onpageload = function () {
    scwin.setReturnValue("─── 결함 재현 준비 완료 ───");
    scwin.setReturnValue("");
    scwin.setReturnValue("재현 방법 :");
    scwin.setReturnValue("  1. [setDisabled(true) - 전체] 버튼 클릭");
    scwin.setReturnValue("  2. target_radio 의 항목 클릭 → 기대 : 이벤트 없음 / 실제 : onfocus, onclick 발생");
    scwin.setReturnValue("  3. target_selectbox 본체 클릭 → 기대 : 이벤트 없음 / 실제 : onclick 발생");
    scwin.setReturnValue("");
    scwin.setReturnValue("[clear] 버튼으로 로그 초기화 후 재현 가능");
    scwin.setReturnValue("");
};



// 전체 setDisabled(true)
scwin.btn_setDisabledTrueAll_onclick = function (e) {
    target_radio.setDisabled(true);
    target_selectbox.setDisabled(true);
    scwin.setReturnValue("[setDisabled(true) - 전체 호출] radio.getDisabled=" + target_radio.getDisabled() + " / selectbox.getDisabled=" + target_selectbox.getDisabled());
};

// 전체 setDisabled(false)
scwin.btn_setDisabledFalseAll_onclick = function (e) {
    target_radio.setDisabled(false);
    target_selectbox.setDisabled(false);
    scwin.setReturnValue("[setDisabled(false) - 전체 호출] radio.getDisabled=" + target_radio.getDisabled() + " / selectbox.getDisabled=" + target_selectbox.getDisabled());
};



// target_radio 이벤트 핸들러
scwin.target_radio_onclick = function (e) {
    scwin.setReturnValue("=====target_radio_onclick 이벤트 발생===== (disabled : " + target_radio.getDisabled() + ")");
};

scwin.target_radio_onfocus = function (e) {
    scwin.setReturnValue("=====target_radio_onfocus 이벤트 발생===== (disabled : " + target_radio.getDisabled() + ")");
};

scwin.target_radio_onchange = function (e) {
    scwin.setReturnValue("=====target_radio_onchange 이벤트 발생===== (disabled : " + target_radio.getDisabled() + ")");
};



// target_selectbox 이벤트 핸들러
scwin.target_selectbox_onclick = function (e) {
    scwin.setReturnValue("=====target_selectbox_onclick 이벤트 발생===== (disabled : " + target_selectbox.getDisabled() + ")");
};

scwin.target_selectbox_onfocus = function (e) {
    scwin.setReturnValue("=====target_selectbox_onfocus 이벤트 발생===== (disabled : " + target_selectbox.getDisabled() + ")");
};

scwin.target_selectbox_onchange = function (e) {
    scwin.setReturnValue("=====target_selectbox_onchange 이벤트 발생===== (disabled : " + target_selectbox.getDisabled() + ")");
};



// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정 (독립 실행용)
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
